@startuml

class Boeing {}

class Airline {
  + Name : string
}

class Contract {
  + DeliveryConditions : string
  + LegalAspects : string
}

class Acquisition {
  + Model : string
  + Price : float
  + OptionsAndCustomizations : string
  + DeliveryDate : date
}

class Employee {
  + Name : string
}

class Salesperson extends Employee {}

Airline "1" -- "*" Contract
Contract "1" *-- "1..*" Acquisition
Contract "*" -- "1" Salesperson
Salesperson "1" -- "*" Contract
Airline "0..1" -- "0..1" Airline : mother_daughter_relationship

@enduml

